<?php global $wpdb; $id=absint($_GET['surah']??1); $surah=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}quran_surahs WHERE id=%d",$id),ARRAY_A); $ayahs=$wpdb->get_results($wpdb->prepare("SELECT id,ayah_number,arabic_text FROM {$wpdb->prefix}quran_ayahs WHERE surah_id=%d ORDER BY ayah_number",$id),ARRAY_A); ?><!doctype html><html><body><main><h1><?php echo esc_html($surah['name_en']??'Surah'); ?></h1><?php foreach($ayahs as $a): ?><p dir="rtl"><span><?php echo esc_html((string)$a['ayah_number']); ?></span> <?php echo esc_html($a['arabic_text']); ?></p><?php endforeach; ?></main></body></html>
